source("smoke_firm_dir/code/fxns/1_paths.R")
library(data.table)
input <- file.path(OUT_DIR,"static_pricing_subgame/observed_recovery_2026-10-27/incumbent_recovery.csv")
out <- file.path(OUT_DIR,"dynamic_entry_exit/constant_marginal_costs_2026-11-03")
dir.create(out,recursive=TRUE,showWarnings=FALSE)
hash <- tools::md5sum(input)
d <- fread(input)
stopifnot(!anyDuplicated(d[,.(brand,month)]),all(is.finite(d$mc)),all(d$mc>0))
costs <- d[,.(mc_constant=median(mc),months=.N,first_month=min(month),last_month=max(month),inversion_only_rows=sum(!in_estimation_sample)),by=brand][order(brand)]
stopifnot(nrow(costs)==9L,sum(costs$months)==540L,all(costs$mc_constant>0))
for(b in costs$brand) stopifnot(costs[brand==b,mc_constant]==median(d[brand==b,mc]))
fwrite(costs,file.path(out,"incumbent_constant_marginal_costs.csv"))
saveRDS(list(costs=costs,method="Unweighted within-firm median across all observed incumbent-roster months",entrant_cost=NULL),file.path(out,"constant_cost_inputs.rds"))
stopifnot(identical(unname(hash),unname(tools::md5sum(input))))
fwrite(data.table(path=input,md5=unname(hash)),file.path(out,"input_hash.csv"))
writeLines(c("Selected initial rule: each incumbent has a time-invariant within-firm median recovered MC, in real dollars/mL.","Medians chosen for consistency with the representative nicotine and xi medians; not a requirement of Markov transitions.","All 540 roster rows included, including 12 BLU 2018 inversion-only rows; no cost recovery or demand fit changed.","Historical windows differ by firm; constants may reflect calendar composition as well as persistent differences.","This simplification does not reproduce each month's original observed-price equilibrium, and does not validate recovered production costs.","Entrant cost assignment remains unspecified; no dynamic equilibrium is solved.","Validation passed: positive finite costs, unique firm-months, 540 observations, nine constants, median reconciliation, unchanged input hash."),file.path(out,"README.txt"))
print(costs)
